#![no_std]
use soroban_sdk::{contract, contracterror, contractimpl, contracttype, token, Address, Env};

// Ledgers are about five seconds apart on Stellar.
const DAY_IN_LEDGERS: u32 = 17_280;
const TTL_THRESHOLD: u32 = 7 * DAY_IN_LEDGERS;
const TTL_EXTEND_TO: u32 = 30 * DAY_IN_LEDGERS;

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
#[repr(u32)]
pub enum Error {
    /// Stake and unstake amounts must be positive.
    InvalidAmount = 1,
    /// The user has less staked than the amount they asked to unstake.
    InsufficientStake = 2,
}

#[contracttype]
pub enum DataKey {
    /// The token that is staked: the native asset's Stellar Asset Contract on testnet.
    Token,
    /// Sum of every user's stake.
    Total,
    /// One user's stake.
    Staked(Address),
}

#[contract]
pub struct StakingContract;

#[contractimpl]
impl StakingContract {
    /// Runs once at deploy time. The token is fixed here, so the contract is ready to use straight away.
    pub fn __constructor(env: Env, token: Address) {
        env.storage().instance().set(&DataKey::Token, &token);
        env.storage().instance().set(&DataKey::Total, &0_i128);
        env.storage()
            .instance()
            .extend_ttl(TTL_THRESHOLD, TTL_EXTEND_TO);
    }

    /// Moves `amount` of the token from `user` into the contract and credits it to `user`.
    pub fn stake(env: Env, user: Address, amount: i128) -> Result<(), Error> {
        user.require_auth();
        if amount <= 0 {
            return Err(Error::InvalidAmount);
        }

        let token = Self::token(&env);
        token::Client::new(&env, &token).transfer(&user, &env.current_contract_address(), &amount);

        let key = DataKey::Staked(user.clone());
        let staked: i128 = env.storage().persistent().get(&key).unwrap_or(0);
        env.storage().persistent().set(&key, &(staked + amount));
        env.storage().persistent().extend_ttl(&key, TTL_THRESHOLD, TTL_EXTEND_TO);

        let total = Self::total(&env);
        env.storage().instance().set(&DataKey::Total, &(total + amount));
        env.storage()
            .instance()
            .extend_ttl(TTL_THRESHOLD, TTL_EXTEND_TO);
        Ok(())
    }

    /// Returns `amount` of the token from the contract to `user`. Fails if `user` has less staked.
    pub fn unstake(env: Env, user: Address, amount: i128) -> Result<(), Error> {
        user.require_auth();
        if amount <= 0 {
            return Err(Error::InvalidAmount);
        }

        let key = DataKey::Staked(user.clone());
        let staked: i128 = env.storage().persistent().get(&key).unwrap_or(0);
        if staked < amount {
            return Err(Error::InsufficientStake);
        }

        // Update the books before the transfer.
        if staked == amount {
            env.storage().persistent().remove(&key);
        } else {
            env.storage().persistent().set(&key, &(staked - amount));
            env.storage().persistent().extend_ttl(&key, TTL_THRESHOLD, TTL_EXTEND_TO);
        }
        let total = Self::total(&env);
        env.storage().instance().set(&DataKey::Total, &(total - amount));
        env.storage()
            .instance()
            .extend_ttl(TTL_THRESHOLD, TTL_EXTEND_TO);

        let token = Self::token(&env);
        token::Client::new(&env, &token).transfer(&env.current_contract_address(), &user, &amount);
        Ok(())
    }

    /// The amount `user` has staked.
    pub fn staked(env: Env, user: Address) -> i128 {
        env.storage()
            .persistent()
            .get(&DataKey::Staked(user))
            .unwrap_or(0)
    }

    /// The amount staked by everyone together.
    pub fn total_staked(env: Env) -> i128 {
        Self::total(&env)
    }

    fn total(env: &Env) -> i128 {
        env.storage().instance().get(&DataKey::Total).unwrap_or(0)
    }

    fn token(env: &Env) -> Address {
        env.storage()
            .instance()
            .get(&DataKey::Token)
            .expect("token is set by the constructor")
    }
}

mod test;

