#![cfg(test)]

use super::*;
use soroban_sdk::{testutils::Address as _, token, Address, Env};

struct Setup<'a> {
    env: Env,
    client: StakingContractClient<'a>,
    token: token::Client<'a>,
    token_admin: token::StellarAssetClient<'a>,
    contract_id: Address,
}

fn setup<'a>() -> Setup<'a> {
    let env = Env::default();
    env.mock_all_auths();

    let admin = Address::generate(&env);
    let asset = env.register_stellar_asset_contract_v2(admin);
    let token_id = asset.address();

    let contract_id = env.register(StakingContract, (token_id.clone(),));
    let client = StakingContractClient::new(&env, &contract_id);
    Setup {
        token: token::Client::new(&env, &token_id),
        token_admin: token::StellarAssetClient::new(&env, &token_id),
        client,
        contract_id,
        env,
    }
}

#[test]
fn new_contract_has_nothing_staked() {
    let s = setup();
    let user = Address::generate(&s.env);
    assert_eq!(s.client.total_staked(), 0);
    assert_eq!(s.client.staked(&user), 0);
}

#[test]
fn stake_moves_tokens_into_the_contract() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.token_admin.mint(&user, &1_000);

    s.client.stake(&user, &400);

    assert_eq!(s.client.staked(&user), 400);
    assert_eq!(s.client.total_staked(), 400);
    assert_eq!(s.token.balance(&user), 600);
    assert_eq!(s.token.balance(&s.contract_id), 400);
}

#[test]
fn stakes_add_up_across_users() {
    let s = setup();
    let alice = Address::generate(&s.env);
    let bob = Address::generate(&s.env);
    s.token_admin.mint(&alice, &1_000);
    s.token_admin.mint(&bob, &1_000);

    s.client.stake(&alice, &100);
    s.client.stake(&alice, &50);
    s.client.stake(&bob, &25);

    assert_eq!(s.client.staked(&alice), 150);
    assert_eq!(s.client.staked(&bob), 25);
    assert_eq!(s.client.total_staked(), 175);
}

#[test]
fn unstake_returns_tokens_to_the_user() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.token_admin.mint(&user, &1_000);
    s.client.stake(&user, &400);

    s.client.unstake(&user, &150);

    assert_eq!(s.client.staked(&user), 250);
    assert_eq!(s.client.total_staked(), 250);
    assert_eq!(s.token.balance(&user), 750);
    assert_eq!(s.token.balance(&s.contract_id), 250);
}

#[test]
fn unstaking_everything_clears_the_stake() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.token_admin.mint(&user, &1_000);
    s.client.stake(&user, &400);

    s.client.unstake(&user, &400);

    assert_eq!(s.client.staked(&user), 0);
    assert_eq!(s.client.total_staked(), 0);
    assert_eq!(s.token.balance(&user), 1_000);
    assert_eq!(s.token.balance(&s.contract_id), 0);
}

#[test]
fn unstaking_more_than_staked_fails_and_changes_nothing() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.token_admin.mint(&user, &1_000);
    s.client.stake(&user, &400);

    let result = s.client.try_unstake(&user, &401);

    assert_eq!(result, Err(Ok(Error::InsufficientStake)));
    assert_eq!(s.client.staked(&user), 400);
    assert_eq!(s.client.total_staked(), 400);
    assert_eq!(s.token.balance(&user), 600);
}

#[test]
fn unstaking_without_any_stake_fails() {
    let s = setup();
    let user = Address::generate(&s.env);

    let result = s.client.try_unstake(&user, &1);

    assert_eq!(result, Err(Ok(Error::InsufficientStake)));
}

#[test]
fn non_positive_amounts_are_rejected() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.token_admin.mint(&user, &1_000);

    assert_eq!(s.client.try_stake(&user, &0), Err(Ok(Error::InvalidAmount)));
    assert_eq!(s.client.try_stake(&user, &-5), Err(Ok(Error::InvalidAmount)));
    s.client.stake(&user, &100);
    assert_eq!(s.client.try_unstake(&user, &0), Err(Ok(Error::InvalidAmount)));
    assert_eq!(s.client.staked(&user), 100);
}

#[test]
fn stake_requires_the_user_to_authorize_it() {
    let env = Env::default();
    let admin = Address::generate(&env);
    let token_id = env.register_stellar_asset_contract_v2(admin).address();
    let contract_id = env.register(StakingContract, (token_id,));
    let client = StakingContractClient::new(&env, &contract_id);
    let user = Address::generate(&env);

    // No authorization has been given, so the call must be rejected.
    assert!(client.try_stake(&user, &100).is_err());
    assert!(client.try_unstake(&user, &100).is_err());
}

