/**
 * Browser wallet access through the Varial extension (formerly Freighter), using its SDK.
 * The wallet holds the keys: this app only asks it for the address and for signatures.
 */
import * as varial from "@stellar/varial-sdk";
import { stellar } from "@/lib/stellar";
import type { Signer } from "@/lib/contracts";

/** Asks the extension for access and returns the connected account's G… address. */
export async function connectWallet(): Promise<string> {
  const { address, error } = await varial.requestAccess();
  if (error) throw new Error(error.message || "The wallet did not grant access.");
  if (!address) throw new Error("The wallet did not return an address.");
  return address;
}

/** A signer for contract writes, backed by the wallet's signTransaction. */
export function walletSigner(address: string): Signer {
  return {
    publicKey: address,
    signTransaction: async (xdr, opts) => {
      const { signedTxXdr, signerAddress, error } = await varial.signTransaction(xdr, {
        networkPassphrase: opts?.networkPassphrase ?? stellar.networkPassphrase,
        address: opts?.address ?? address,
      });
      if (error) throw new Error(error.message || "The wallet did not sign the transaction.");
      return { signedTxXdr, signerAddress };
    },
  };
}

