"use client";

import { useRouter } from "next/navigation";
import { useState, type FormEvent } from "react";
import { staking } from "@/lib/contracts";
import { connectWallet, walletSigner } from "@/lib/wallet";

type Notice = { kind: "ok" | "error"; text: string };

/** Connects a wallet and stakes an amount of XLM, entered in stroops (1 XLM = 10,000,000 stroops). */
export function StakeForm() {
  const router = useRouter();
  const [address, setAddress] = useState<string | null>(null);
  const [amount, setAmount] = useState("");
  const [busy, setBusy] = useState(false);
  const [notice, setNotice] = useState<Notice | null>(null);

  async function onConnect() {
    setBusy(true);
    setNotice(null);
    try {
      setAddress(await connectWallet());
    } catch (error) {
      setNotice({ kind: "error", text: reason(error) });
    } finally {
      setBusy(false);
    }
  }

  async function onStake(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!address) return;
    const text = amount.trim();
    if (!/^[1-9][0-9]*$/.test(text)) {
      setNotice({ kind: "error", text: "Enter a whole number of stroops, greater than zero." });
      return;
    }
    setBusy(true);
    setNotice(null);
    try {
      const value = BigInt(text);
      const client = staking(walletSigner(address));
      const tx = await client.stake({ user: address, amount: value });
      await tx.signAndSend();
      setAmount("");
      setNotice({ kind: "ok", text: `Staked ${text} stroops.` });
      router.refresh(); // Re-read the total from the contract.
    } catch (error) {
      setNotice({ kind: "error", text: reason(error) });
    } finally {
      setBusy(false);
    }
  }

  return (
    <section>
      {address ? (
        <p>
          Wallet: <code data-testid="wallet-address">{address}</code>
        </p>
      ) : (
        <button type="button" data-testid="connect-wallet" onClick={onConnect} disabled={busy}>
          Connect wallet
        </button>
      )}

      <form onSubmit={onStake}>
        <label>
